-- Second Ace-authored BBA Year 2 Semester 1 exam-preparation set.
-- Original questions are informed by course topics and public MUST paper patterns.
-- They are not official examination questions, lecturer-approved memoranda or a full syllabus.
-- Stable IDs make this seed safe to reapply without duplicating quizzes or questions.

WITH new_quizzes(id,title,course_code,description,status) AS (
  VALUES
    ('a1100000-0000-4000-8000-000000000001','Ace Practice · Exam Preparation II','BFB3200','Original Ace exam-preparation questions on workforce planning, job evaluation, recruitment, training, performance management, employee relations and HR metrics. These are not official examination questions or a lecturer-issued marking scheme.','published'),
    ('a1100000-0000-4000-8000-000000000002','Ace Practice · Exam Preparation II','BFB3201','Original Ace questions on agency, acceptance, alternative dispute resolution, customary law, delegated legislation, statutory interpretation, defamation and employer liability. The topic mix is informed by the public MUST January 2026 BFB3201 paper; no exam question is reproduced.','published'),
    ('a1100000-0000-4000-8000-000000000003','Ace Practice · Exam Preparation II','BFB3202','Original Ace questions on opportunity recognition, customer discovery, feasibility, business models, cash flow and growth decisions. These are Ace-developed practice items, not official examination questions.','published'),
    ('a1100000-0000-4000-8000-000000000004','Ace Practice · Exam Preparation II','BFB3203','Original Ace questions on leadership approaches, motivation, delegation, teams, conflict, ethical judgement and change. They test application rather than recall alone and are not official examination questions.','published'),
    ('a1100000-0000-4000-8000-000000000005','Ace Practice · Exam Preparation II','BFB3205','Original Ace questions on PR planning, stakeholder research, media relations, crisis communication, message design and evaluation. These are practice questions, not official MUST examination questions.','published'),
    ('a1100000-0000-4000-8000-000000000006','Ace Practice · Exam Preparation II','BFC3227','Original Ace calculations and applications on cost classification, stock control, costing methods, labour, EOQ, cost behaviour and process costing. A related older MUST BFC3227 archive paper is labelled B.Com; current BBA assessment coverage should be confirmed with the School.','published')
),
upserted_quizzes AS (
  INSERT INTO public.ace_quizzes (id,title,course_code,description,status)
  SELECT id,title,course_code,description,status FROM new_quizzes
  ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    course_code = EXCLUDED.course_code,
    description = EXCLUDED.description,
    status = EXCLUDED.status
  RETURNING id,course_code
),
question_data(id,course_code,sort_order,prompt,options,correct_index,explanation) AS (
  VALUES
    ('a1200000-0000-4000-8000-000000000001','BFB3200',1,'A firm forecasts that it will need 18 additional sales staff next semester. It already has 6 suitable employees who can be promoted. Before recruiting externally, what should HR do?','["Compare projected demand with internal supply and identify the remaining staffing gap","Recruit 18 people immediately","Cancel all training plans","Reduce the number of existing job descriptions"]'::jsonb,0,'Workforce planning compares future staffing demand with internal supply. If six suitable employees can be promoted, the remaining gap is 12, subject to role and timing checks.'),
    ('a1200000-0000-4000-8000-000000000002','BFB3200',2,'Job evaluation is primarily used to:','["Measure an individual employee''s annual performance","Assess the relative value of different jobs to establish a fair internal pay structure","Identify which applicants should be interviewed","Calculate the organisation''s annual tax liability"]'::jsonb,1,'Job evaluation assesses the relative value of roles, usually using factors such as responsibility, skill, effort and working conditions. It is not the same as appraising the person currently in the role.'),
    ('a1200000-0000-4000-8000-000000000003','BFB3200',3,'A vacancy is filled by promoting a qualified employee from another department. Which is a potential advantage of this internal recruitment approach?','["It guarantees that no training will be required","It always introduces new external ideas","The employee already understands parts of the organisation and the employer has some performance history","It removes the need to define the job"]'::jsonb,2,'Internal recruitment can reduce induction time and provide known performance evidence, although it may limit the external talent pool and create another vacancy.'),
    ('a1200000-0000-4000-8000-000000000004','BFB3200',4,'A selection test gives very similar results when the same applicant takes it again under comparable conditions. This most directly indicates:','["Reliability","Job enlargement","Induction","Labour turnover"]'::jsonb,0,'Reliability concerns consistency of measurement. Validity is the separate question of whether the test measures what it is intended to measure.'),
    ('a1200000-0000-4000-8000-000000000005','BFB3200',5,'Which combination best represents the three common levels of training-needs analysis?','["Price, promotion and place","Organisation, task and individual","Assets, liabilities and equity","Planning, budgeting and auditing"]'::jsonb,1,'Training needs can be examined at organisational level, at task or job level, and at the individual employee level.'),
    ('a1200000-0000-4000-8000-000000000006','BFB3200',6,'Employees attend a customer-service course but return to a workplace where supervisors discourage them from using the new approach. The main problem is:','["Excessive job evaluation","A lack of recruitment advertising","Weak transfer of training to the job","An inaccurate organisational chart"]'::jsonb,2,'Training transfer is the application of learning at work. Supervisor support, opportunities to practise and aligned processes help learning transfer into performance.'),
    ('a1200000-0000-4000-8000-000000000007','BFB3200',7,'A supervisor rates an employee poorly because of one mistake made during the final week, ignoring strong performance throughout the year. Which appraisal error is most evident?','["Recency effect","Job rotation","Workforce forecasting","External recruitment"]'::jsonb,0,'The recency effect occurs when recent events receive disproportionate weight in an evaluation.'),
    ('a1200000-0000-4000-8000-000000000008','BFB3200',8,'An employee submits a formal grievance about unfair shift allocation. Which response best supports procedural fairness?','["Ignore the complaint until the employee resigns","Investigate the facts, hear the employee, apply the relevant policy consistently and communicate the outcome","Immediately discipline the employee for complaining","Ask colleagues to vote on whether the complaint is valid"]'::jsonb,1,'A fair grievance process should be timely, evidence-based, consistent and give the employee a meaningful opportunity to be heard.'),
    ('a1200000-0000-4000-8000-000000000009','BFB3200',9,'Two employees perform jobs assessed at the same internal value, but one is paid substantially less without a clear job-related reason. Which reward principle is most directly in question?','["External recruitment","Training transfer","Internal pay equity","Performance counselling"]'::jsonb,2,'Internal equity concerns the perceived fairness of pay relationships between jobs within the same organisation.'),
    ('a1200000-0000-4000-8000-000000000010','BFB3200',10,'A company had an average of 80 employees during a year and 12 employees left during that year. Using the simple turnover formula, what was the turnover rate?','["8%","12%","15%","20%"]'::jsonb,2,'Turnover rate = number of leavers ÷ average number employed × 100 = 12 ÷ 80 × 100 = 15%.'),
    ('a1200000-0000-4000-8000-000000000011','BFB3201',1,'An agent enters a contract without authority, but the principal later adopts the whole transaction with knowledge of the material facts. This may amount to:','["Ratification","Novation by the agent","Delegated legislation","A criminal conviction"]'::jsonb,0,'Ratification is the principal''s later adoption of an act initially done without authority, subject to legal requirements such as the principal''s capacity and knowledge of material facts.'),
    ('a1200000-0000-4000-8000-000000000012','BFB3201',2,'A supplier offers 500 units at KSh 200 each. The buyer replies, ''I accept, but only if you deliver 600 units at the same total price.'' The reply is generally:','["An unconditional acceptance","A counter-offer","A completed performance","A court order"]'::jsonb,1,'An acceptance must correspond to the offer. A response that changes material terms is generally treated as a counter-offer rather than an unconditional acceptance.'),
    ('a1200000-0000-4000-8000-000000000013','BFB3201',3,'In mediation, the neutral third party normally:','["Imposes a binding judgment after hearing evidence","Acts as legal representative for one party","Helps the parties explore settlement without deciding the dispute for them","Automatically cancels the original contract"]'::jsonb,2,'Mediation is facilitative. The parties retain control over whether they reach an agreement; arbitration, by contrast, commonly involves a decision by the arbitrator.'),
    ('a1200000-0000-4000-8000-000000000014','BFB3201',4,'In Kenyan law, the application of African customary law in a civil matter is subject to limits that include whether the rule is repugnant to justice and morality or inconsistent with written law. What is the main point of this test?','["Customary law is automatically superior to every statute","Customary law is applied without considering the facts","Customary law may be considered, but its application is subject to legal limits","Only customs written in a company handbook are recognised"]'::jsonb,2,'The question tests the limits governing the application of customary law. The relevant statutory framework and facts should be checked in the prescribed Kenyan legal materials.'),
    ('a1200000-0000-4000-8000-000000000015','BFB3201',5,'A regulation is made by a minister under powers expressly granted by an Act of Parliament. This is an example of:','["Delegated legislation","A private contract","A judicial precedent","A constitutional amendment passed by referendum"]'::jsonb,0,'Delegated legislation is made by a body or person exercising law-making powers granted by primary legislation, within the limits of the enabling Act.'),
    ('a1200000-0000-4000-8000-000000000016','BFB3201',6,'Which statement best distinguishes a civil case from a criminal case?','["A civil case always involves the state prosecuting an offence","A criminal case concerns an alleged public offence prosecuted under criminal law, while a civil case commonly resolves private rights and liabilities","A civil case cannot involve money","A criminal case is always decided by an arbitrator"]'::jsonb,1,'The distinction concerns the nature of the proceedings, parties, purpose and possible consequences. The exact procedure and standard of proof depend on applicable law.'),
    ('a1200000-0000-4000-8000-000000000017','BFB3201',7,'A court interprets a statutory provision by considering the problem the legislation was intended to remedy. Which interpretive approach is most closely associated with this reasoning?','["The mischief rule","The doctrine of privity","The rule in Hadley v Baxendale","The doctrine of ultra vires in company finance"]'::jsonb,0,'The mischief approach asks what defect or problem the legislation sought to address and interprets the provision with that purpose in view.'),
    ('a1200000-0000-4000-8000-000000000018','BFB3201',8,'A business is sued for a published statement that damaged another person''s reputation. Which is a recognised general category of defence that may be relevant, depending on the evidence and applicable law?','["The statement was popular","The publisher used a large font","The statement was true and the legal requirements for the defence are met","The claimant did not reply on social media"]'::jsonb,2,'Truth or justification may provide a defence where the applicable legal requirements are satisfied. Defamation questions must be analysed using the relevant Kenyan law and facts.'),
    ('a1200000-0000-4000-8000-000000000019','BFB3201',9,'A delivery driver negligently injures a customer while carrying out an assigned delivery for an employer. The customer considers suing the employer as well as the driver. The legal principle most relevant is:','["Vicarious liability","Consideration","Promissory estoppel only","The rule against perpetuities"]'::jsonb,0,'Vicarious liability can make an employer liable for an employee''s tort committed in the course of employment, subject to the applicable legal test.'),
    ('a1200000-0000-4000-8000-000000000020','BFB3201',10,'A company wants to rely on an exclusion clause printed on the back of a receipt. The customer received the receipt only after paying. What should be examined first?','["Whether the company has a colourful logo","Whether the clause was incorporated into the contract with adequate notice or another legally effective basis","Whether the customer has a bank account","Whether the receipt was printed in black ink"]'::jsonb,1,'The key issue is incorporation: whether the term became part of the contract, including the timing and adequacy of notice. Other statutory and common-law limits may also apply.'),
    ('a1200000-0000-4000-8000-000000000021','BFB3202',1,'A founder has received many compliments about a proposed product but no one has tried to buy it. What is the strongest next experiment?','["Ask friends whether the logo looks attractive","Offer a small paid pilot to a clearly defined customer group and observe actual behaviour","Rent a large shop immediately","Hire a full sales team before testing demand"]'::jsonb,1,'A paid pilot tests behaviour and willingness to commit, which is stronger evidence than compliments or hypothetical interest.'),
    ('a1200000-0000-4000-8000-000000000022','BFB3202',2,'A business idea is most likely to become a feasible opportunity when:','["The founder personally likes it","There are no competitors","A reachable customer group has a meaningful problem and the proposed solution can be delivered on viable terms","The idea can be described in one sentence"]'::jsonb,2,'Opportunity assessment combines customer need, market access, a deliverable solution and a sustainable economic model. The presence of competitors is not automatically a weakness.'),
    ('a1200000-0000-4000-8000-000000000023','BFB3202',3,'A founder interviews recent customers and asks what they did the last time the problem occurred. Why is this generally more useful than asking, ''Would you buy my idea?''','["Past behaviour and real workarounds provide more concrete evidence than hypothetical approval","It guarantees that customers will buy","It removes the need to test price","It proves the market is large enough"]'::jsonb,0,'Questions about recent behaviour reveal actual problems, alternatives, costs and purchasing patterns; stated intention alone can overstate demand.'),
    ('a1200000-0000-4000-8000-000000000024','BFB3202',4,'A business sells a service for KSh 900 per job. Variable cost is KSh 540 per job. Monthly fixed costs are KSh 18,000. How many jobs are required to break even?','["20","30","40","50"]'::jsonb,1,'Contribution per job = 900 − 540 = KSh 360. Break-even volume = 18,000 ÷ 360 = 50 jobs. Correction: the correct option is 50.'),
    ('a1200000-0000-4000-8000-000000000025','BFB3202',5,'A start-up invoices customers immediately but allows payment after 45 days, while suppliers demand cash after 7 days. Which risk is most direct?','["A shortage of trademarks","A working-capital and cash-timing gap","An automatic increase in gross margin","A decline in the number of competitors"]'::jsonb,1,'The business may need to fund the 38-day gap between supplier payment and customer collection, even if the sale is profitable.'),
    ('a1200000-0000-4000-8000-000000000026','BFB3202',6,'A value proposition should clearly identify:','["The founder''s preferred office design","The customer group, problem addressed and outcome the offer provides","Only the business registration number","Every future product the company may ever sell"]'::jsonb,1,'A useful value proposition explains for whom the offer is intended, which problem it solves and why the outcome matters.'),
    ('a1200000-0000-4000-8000-000000000027','BFB3202',7,'Which assessment is most directly concerned with whether the business can obtain the skills, equipment, suppliers and processes needed to deliver the offer?','["Operational feasibility","Brand awareness","Market segmentation only","Legal personality only"]'::jsonb,0,'Operational feasibility checks whether the venture can actually deliver the proposed product or service with available or obtainable resources and processes.'),
    ('a1200000-0000-4000-8000-000000000028','BFB3202',8,'A founder tests two price points with comparable customer groups. Which outcome should be compared before choosing the price?','["Revenue only, regardless of costs","The number of social media likes","Contribution, conversion and customer response, while controlling for differences between groups","The founder''s preferred colour"]'::jsonb,2,'A price experiment should evaluate commercial outcomes such as conversion, contribution and demand. Revenue alone can hide lower margins or changes in volume.'),
    ('a1200000-0000-4000-8000-000000000029','BFB3202',9,'A new venture starts with a narrow customer segment and expands only after its delivery process works reliably. This approach is best described as:','["Evidence-led staged growth","Diversification without evidence","Market exit","A guaranteed monopoly strategy"]'::jsonb,0,'A staged approach limits exposure while the venture validates demand, operations and economics before scaling.'),
    ('a1200000-0000-4000-8000-000000000030','BFB3202',10,'A business model differs from a value proposition because the business model also explains:','["How the venture creates, delivers and captures value, including activities, partners, costs and revenue","Only the business name","Only the product''s colour","The founder''s academic grades"]'::jsonb,0,'The value proposition focuses on customer value. The business model explains the wider system through which the venture operates and earns revenue.'),
    ('a1200000-0000-4000-8000-000000000031','BFB3203',1,'A new employee is enthusiastic but has little experience with a task. A leader should first consider an approach that provides:','["Clear direction, demonstration and close support while competence develops","No feedback until the annual appraisal","Complete autonomy without context","Punishment for asking questions"]'::jsonb,0,'A developing employee may need clear direction and support. A situational approach adapts leadership behaviour to competence and commitment rather than using one style for every person.'),
    ('a1200000-0000-4000-8000-000000000032','BFB3203',2,'A manager motivates staff mainly through agreed targets, performance monitoring and contingent rewards. This most closely resembles:','["Transactional leadership","Servant leadership only","Laissez-faire leadership","Charismatic authority without exchange"]'::jsonb,0,'Transactional leadership uses exchanges such as agreed performance expectations and rewards or corrective action.'),
    ('a1200000-0000-4000-8000-000000000033','BFB3203',3,'A leader encourages employees to question established methods, develop new ideas and connect their work to a shared purpose. This most closely resembles:','["Transformational leadership","Purely coercive supervision","Avoidant leadership","A clerical control procedure"]'::jsonb,0,'Transformational leadership emphasises purpose, inspiration, intellectual stimulation and individual consideration.'),
    ('a1200000-0000-4000-8000-000000000034','BFB3203',4,'A team leader delegates responsibility but gives no authority, deadline or resources. What is the most likely result?','["The employee has everything needed to succeed","The task may fail because accountability is not matched by clear authority and support","The task is automatically completed faster","Delegation removes the leader''s accountability"]'::jsonb,1,'Effective delegation clarifies the expected output, authority, resources, timeframe and reporting. The manager retains overall accountability.'),
    ('a1200000-0000-4000-8000-000000000035','BFB3203',5,'Two departments disagree about a shared deadline. Which first step is most likely to support constructive conflict resolution?','["Assume one department is acting in bad faith","Clarify shared objectives, dependencies, constraints and the evidence behind each position","Escalate immediately without discussion","Withhold information until the deadline passes"]'::jsonb,1,'Task conflict is best addressed by surfacing interests, facts and dependencies before selecting a solution.'),
    ('a1200000-0000-4000-8000-000000000036','BFB3203',6,'A leader learns that a high-performing employee has manipulated results. The most defensible response is to:','["Ignore the conduct because targets were met","Apply the relevant process fairly, investigate evidence and protect the integrity of reporting","Delete the performance records","Reward the employee privately"]'::jsonb,1,'Ethical leadership requires integrity and fair process. Strong results do not justify falsified records or unequal treatment.'),
    ('a1200000-0000-4000-8000-000000000037','BFB3203',7,'A team has capable members but unclear roles, duplicated work and missed handovers. Which leadership action is most direct?','["Clarify responsibilities, decision rights and coordination routines","Increase the number of unrelated meetings","Remove all deadlines","Encourage each member to create a separate work plan without coordination"]'::jsonb,0,'Role clarity and coordination routines reduce duplication and missed dependencies.'),
    ('a1200000-0000-4000-8000-000000000038','BFB3203',8,'An employee is motivated by mastering a difficult task and gaining professional autonomy. These are examples of:','["Intrinsic motivators","Only statutory deductions","External market barriers","Fixed production overheads"]'::jsonb,0,'Intrinsic motivation arises from the work itself, such as mastery, purpose, interest and autonomy.'),
    ('a1200000-0000-4000-8000-000000000039','BFB3203',9,'A leader invites affected staff to help shape a new work process and explains why the change is necessary. This can improve implementation because it:','["Guarantees there will be no resistance","Builds understanding, participation and ownership","Removes the need for training","Makes the change legally binding without approval"]'::jsonb,1,'Participation and clear communication can improve understanding and commitment, though they do not guarantee universal agreement.'),
    ('a1200000-0000-4000-8000-000000000040','BFB3203',10,'After a project setback, a team reviews what happened, identifies process causes and agrees changes for the next cycle. This is an example of:','["Blame allocation without learning","Reflective learning and continuous improvement","Avoidance of responsibility","A recruitment exercise"]'::jsonb,1,'A structured review converts experience into evidence and improvement actions rather than focusing only on individual blame.'),
    ('a1200000-0000-4000-8000-000000000041','BFB3205',1,'A PR team begins a campaign by identifying affected groups, their concerns and the change the campaign should achieve. This is mainly part of:','["Research and situation analysis","Media placement after the campaign","Final evaluation only","Production of promotional merchandise"]'::jsonb,0,'Research establishes the context, stakeholders, issues and baseline information needed for a suitable communication plan.'),
    ('a1200000-0000-4000-8000-000000000042','BFB3205',2,'A university wants to communicate a new fee policy. Which is the strongest starting point for a stakeholder plan?','["Send the same message to everyone without identifying their needs","Identify affected groups, their information needs, likely concerns and suitable channels","Target only people who already agree","Avoid collecting questions"]'::jsonb,1,'Stakeholder analysis identifies who is affected, what they need to know and how communication should be adapted without changing the underlying facts.'),
    ('a1200000-0000-4000-8000-000000000043','BFB3205',3,'A newspaper independently publishes a story about a student initiative after receiving a factual media release. This coverage is best classified as:','["Paid media","Earned media","Owned media","Internal communication"]'::jsonb,1,'Earned media is coverage or attention received through editorial or public interest rather than purchasing the placement.'),
    ('a1200000-0000-4000-8000-000000000044','BFB3205',4,'Which opening for a press release is most effective?','["A long history of the organisation before mentioning the news","A clear first paragraph stating the main development, who is involved, when and why it matters","A slogan with no verifiable detail","An unverified claim that the event is the biggest in the world"]'::jsonb,1,'A strong lead puts the most newsworthy and verifiable facts first, then adds supporting detail and context.'),
    ('a1200000-0000-4000-8000-000000000045','BFB3205',5,'A service disruption affects students and the cause is still being investigated. What should the PR team communicate first?','["Acknowledge the disruption, state verified facts, explain what is not yet known and give the next update time","Speculate about who is responsible","Remain silent until every technical detail is available","Blame a named staff member before an investigation"]'::jsonb,0,'Crisis communication should be timely, accurate and empathetic. It is better to distinguish known from unknown than to speculate.'),
    ('a1200000-0000-4000-8000-000000000046','BFB3205',6,'A campaign reaches 20,000 people, but the organisation has no evidence that the audience understood the message. Which is the best next evaluation step?','["Count more posters only","Measure recall, comprehension or another audience response related to the objective","Assume reach proves behaviour change","Stop evaluation"]'::jsonb,1,'Reach is an output measure. Recall and comprehension are audience-response measures; behaviour and policy outcomes are separate levels of evaluation.'),
    ('a1200000-0000-4000-8000-000000000047','BFB3205',7,'A company invites employees to ask questions, responds to feedback and adjusts its internal messages based on concerns. This approach is closest to:','["Two-way communication","One-way publicity only","Silent monitoring","Uncontrolled rumour"]'::jsonb,0,'Two-way communication includes listening and response, rather than only transmitting information.'),
    ('a1200000-0000-4000-8000-000000000048','BFB3205',8,'A rumour about a safety incident begins circulating online. Before issuing a detailed correction, the communication team should:','["Share the rumour widely to increase attention","Verify the facts with the responsible teams and preserve evidence","Delete all internal records","Publish an apology for facts that have not been established"]'::jsonb,1,'Verification protects credibility and helps the organisation correct inaccurate information without creating new inaccuracies.'),
    ('a1200000-0000-4000-8000-000000000049','BFB3205',9,'Which metric best indicates whether a public awareness campaign achieved a change in safety behaviour?','["Number of press releases distributed","Number of posters printed","Observed or reliably measured change in the targeted safety behaviour","Number of internal meetings held"]'::jsonb,2,'Behavioural outcomes align more directly with the campaign objective than production or distribution counts.'),
    ('a1200000-0000-4000-8000-000000000050','BFB3205',10,'A PR practitioner is asked to publish a favourable claim that has not been substantiated. The most appropriate response is to:','["Publish it because it is attractive","Present it as a rumour","Request evidence and use accurate, qualified wording rather than making an unsupported claim","Attribute it to an anonymous source without checking"]'::jsonb,2,'Professional communication requires accurate substantiated information. A claim should be checked and qualified rather than presented as fact without evidence.'),
    ('a1200000-0000-4000-8000-000000000051','BFC3227',1,'Which combination makes up prime cost?','["Direct materials, direct labour and direct expenses","Direct labour and production overhead only","Administration overhead and selling costs","Fixed production overhead and finance cost"]'::jsonb,0,'Prime cost comprises direct materials, direct labour and direct expenses directly attributable to the cost object.'),
    ('a1200000-0000-4000-8000-000000000052','BFC3227',2,'Conversion cost is generally calculated as:','["Direct materials plus direct expenses","Direct labour plus production overhead","Selling and distribution cost plus administration","Prime cost plus finance charges"]'::jsonb,1,'Conversion cost represents the costs of converting materials into finished output, commonly direct labour plus production overhead.'),
    ('a1200000-0000-4000-8000-000000000053','BFC3227',3,'A job costing system is most appropriate when:','["Output is homogeneous and continuously produced in large quantities","Each customer order or job can be separately identified and costed","All units are identical and cannot be distinguished","Only financial statements are required"]'::jsonb,1,'Job costing accumulates costs for identifiable jobs or orders. Process costing is more suitable for continuous homogeneous production.'),
    ('a1200000-0000-4000-8000-000000000054','BFC3227',4,'Annual demand is 2,400 units, the cost of placing an order is KSh 500 and annual holding cost is KSh 20 per unit. What is the approximate economic order quantity?','["240 units","300 units","346 units","480 units"]'::jsonb,2,'EOQ = square root of (2 × annual demand × ordering cost ÷ holding cost) = √(2 × 2,400 × 500 ÷ 20) ≈ 346 units.'),
    ('a1200000-0000-4000-8000-000000000055','BFC3227',5,'Opening inventory is 100 units at KSh 10 each and a further 200 units are purchased at KSh 13 each. Under a simple weighted-average method, what is the average cost per unit before any issue?','["KSh 10.00","KSh 11.00","KSh 12.00","KSh 13.00"]'::jsonb,2,'Weighted average cost = (100 × 10 + 200 × 13) ÷ 300 = 3,600 ÷ 300 = KSh 12 per unit.'),
    ('a1200000-0000-4000-8000-000000000056','BFC3227',6,'A company has total costs of KSh 18,000 at 900 units and KSh 12,000 at 500 units. Using the high-low method, what is the estimated variable cost per unit?','["KSh 10","KSh 12","KSh 15","KSh 20"]'::jsonb,2,'Variable cost per unit = change in total cost ÷ change in activity = (18,000 − 12,000) ÷ (900 − 500) = 6,000 ÷ 400 = KSh 15.'),
    ('a1200000-0000-4000-8000-000000000057','BFC3227',7,'Within the relevant range, which statement about fixed cost is generally correct?','["Fixed cost per unit always remains constant","Total fixed cost remains constant while fixed cost per unit changes with activity","Total fixed cost changes in direct proportion to output","Fixed cost is always irrelevant to every decision"]'::jsonb,1,'Within the relevant range, total fixed cost is assumed constant; the fixed cost per unit falls as output increases and rises as output decreases.'),
    ('a1200000-0000-4000-8000-000000000058','BFC3227',8,'Under absorption costing, fixed production overhead is:','["Treated only as a period expense","Included in the cost of inventory and production","Excluded from product cost in all cases","Treated as a selling commission"]'::jsonb,1,'Absorption costing includes fixed manufacturing overhead in product cost. Marginal costing treats fixed production overhead as a period cost.'),
    ('a1200000-0000-4000-8000-000000000059','BFC3227',9,'A process receives 1,000 units of input. Normal loss is 5% of input and actual good output is 930 units. Assuming no opening or closing work in progress, what is the abnormal loss?','["10 units","20 units","50 units","70 units"]'::jsonb,1,'Normal loss = 5% × 1,000 = 50 units. Expected output is 950 units; actual output is 930, so abnormal loss is 20 units.'),
    ('a1200000-0000-4000-8000-000000000060','BFC3227',10,'Which reason best explains why cost-accounting profit may differ from financial-accounting profit?','["The two systems always record identical information","Some costs, overheads, stock valuations or items may be treated differently and require reconciliation","Financial accounting never records expenses","Cost accounting ignores production"]'::jsonb,1,'Different objectives and conventions can produce differences in treatment, classification or overhead absorption. A reconciliation explains the difference.')
)
INSERT INTO public.ace_questions (id,quiz_id,prompt,options,correct_index,explanation,sort_order)
SELECT
  q.id,
  u.id,
  q.prompt,
  q.options,
  q.correct_index::smallint,
  q.explanation,
  q.sort_order::smallint
FROM question_data q
JOIN upserted_quizzes u ON u.course_code = q.course_code
ON CONFLICT (id) DO UPDATE SET
  quiz_id = EXCLUDED.quiz_id,
  prompt = EXCLUDED.prompt,
  options = EXCLUDED.options,
  correct_index = EXCLUDED.correct_index,
  explanation = EXCLUDED.explanation,
  sort_order = EXCLUDED.sort_order;
